#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int RV = 10;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    int total = 0;

    for (int &x : a) {
        cin >> x;
        total += x;
    }

    sort(a.begin(), a.end());

    const int width = N + 1;
    vector<int> can((total + 1) * width, 0);

    auto dp = [&](int sum, int count) -> int& {
        return can[sum * width + count];
    };

    dp(0, 0) = 1;

    for (int i = 0; i < N;) {
        int j = i + 1;
        while (j < N && a[j] == a[i]) {
            ++j;
        }

        const int value = a[i];
        const int amount = j - i;

        for (int sum = total; sum >= 0; --sum) {
            for (int count = N; count >= 0; --count) {
                for (int k = 1;
                     k <= amount && k <= count && k * value <= sum;
                     ++k) {
                    dp(sum, count) += dp(sum - k * value, count - k);
                    if (dp(sum, count) > RV) {
                        dp(sum, count) = RV;
                    }
                }
            }
        }

        i = j;
    }

    int answer = 0;

    for (int i = 0; i < N;) {
        int j = i + 1;
        while (j < N && a[j] == a[i]) {
            ++j;
        }

        const int amount = j - i;

        for (int k = 1; k <= amount; ++k) {
            const int weight = k * a[i];

            if (dp(weight, k) == 1 ||
                dp(total - weight, N - k) == 1) {
                answer = max(answer, k);
            }
        }

        i = j;
    }

    cout << answer << '\n';
    return 0;
}

