#include <iostream>
#include <cstdio>
#include <algorithm>
#include <cassert>

using namespace std;

const int MAXN = 110;
const int MAXV = 110;
const int RV = 10;

int N, a[MAXN + 1];
int tot;

int can[MAXN * MAXV + 1][MAXN + 1];

void work(int sw, int am) {
    for (int i = tot; i >= 0; i--) {
        for (int j = N; j >= 0; j--) {
            for (int k = 1; k <= am && k * sw <= i && k <= j; k++) {
                can[i][j] += can[i - k * sw][j - k];
                if (can[i][j] > RV) can[i][j] = RV;
            }
        }
    }
}

int main() {
    scanf("%d", &N);

    tot = 0;
    for (int i = 1; i <= N; i++) {
        scanf("%d", &a[i]);
        tot += a[i];
    }

    sort(a + 1, a + N + 1);

    for (int i = 0; i <= tot; i++)
        for (int j = 0; j <= N; j++)
            can[i][j] = 0;

    can[0][0] = 1;

    for (int i = 1, j; i <= N; i = j) {
        for (j = i + 1; j <= N && a[i] == a[j]; j++);
        work(a[i], j - i);
    }

    int ans = 0;
    for (int i = 1, j; i <= N; i = j) {
        for (j = i + 1; j <= N && a[i] == a[j]; j++);

        int count = j - i;
        int tw = count * a[i];

        assert(can[tw][count] >= 1 &&
               can[tot - tw][N - count] >= 1);

        if (can[tw][count] == 1 ||
            can[tot - tw][N - count] == 1) {
            ans = max(ans, count);
        }
    }

    printf("%d\n", ans);

    return 0;
}

